#!/usr/bin/env bash
# NovaRay installer: applies the NovaRay changes to your fork of 2dust/v2rayNG and pushes them.
# Run it from the root of your fork (for example in GitHub Codespaces):  bash install-novaray.sh
set -euo pipefail

BASE_COMMIT=57907cf354d9769200ed4717b4430d605abe0952
PATCH_FILE=$(mktemp)
trap 'rm -f "$PATCH_FILE"' EXIT

if [ ! -f V2rayNG/app/build.gradle.kts ]; then
  echo "Ошибка: запустите скрипт в корне форка v2rayNG (там, где папка V2rayNG)." >&2
  exit 1
fi

sed -n '/^__PATCH_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d > "$PATCH_FILE"

git config user.name  >/dev/null 2>&1 || git config user.name  "NovaRay builder"
git config user.email >/dev/null 2>&1 || git config user.email "novaray@users.noreply.github.com"

FORCE_PUSH=""
if git apply --check "$PATCH_FILE" 2>/dev/null; then
  echo "Патч подходит к текущей версии v2rayNG."
else
  echo "Upstream изменился, откатываюсь на проверенную версию $BASE_COMMIT ..."
  git fetch --quiet https://github.com/2dust/v2rayNG.git master || true
  git cat-file -e "$BASE_COMMIT^{commit}" 2>/dev/null || git fetch --quiet https://github.com/2dust/v2rayNG.git "$BASE_COMMIT"
  git reset --hard "$BASE_COMMIT"
  git submodule update --init --recursive || true
  FORCE_PUSH="--force"
fi

git apply "$PATCH_FILE"
git add -A
git commit -q -m "NovaRay: Happ compatibility, subscription routing/announce, auto-select fastest, RU defaults, CI"
BRANCH=$(git rev-parse --abbrev-ref HEAD)
git push $FORCE_PUSH origin "HEAD:$BRANCH"

echo
echo "Готово! Откройте вкладку Actions в своём репозитории: сборка APK уже запущена."
echo "Когда сборка закончится (зелёная галочка), APK появится в разделе Releases."
exit 0
